import { ref, inject, provide, type InjectionKey, type Ref } from 'vue';
import type { BinaryObject } from '@/01-models/types';
import type { BinaryObjectId } from '@/01-models/ids';

// A local preview may own bytes that have never been written to storage.
// This is not a persisted BinaryObject or message DTO.
export type BinaryObjectPreviewItem = BinaryObject & { memoryBlob: Blob | undefined };

interface PreviewState {
  objects: BinaryObjectPreviewItem[],
  initialId: BinaryObjectId,
}

interface ImagePreviewApi {
  state: Ref<PreviewState | null>,
  openPreview: ({ objects, initialId }: { objects: PreviewState['objects'], initialId: PreviewState['initialId'] }) => void,
  closePreview: () => void,
  TEST_ONLY: Record<never, never>,
}

export type ContextualPreviewHandler = ({ id }: { id: BinaryObjectId }) => Promise<void>;

export const MESSAGE_CONTEXTUAL_PREVIEW_KEY: InjectionKey<ContextualPreviewHandler> = Symbol('MessageContextualPreview');

const PREVIEW_KEY: InjectionKey<{
  state: Ref<PreviewState | null>,
  openPreview: ({ objects, initialId }: { objects: PreviewState['objects'], initialId: PreviewState['initialId'] }) => void,
  closePreview: () => void,
}> = Symbol('ImagePreview');

/**
 * Image Preview Composable
 *
 * Can be used either as a singleton or as a scoped instance via provide/inject.
 */
export function useImagePreview({ scoped = false }: { scoped?: boolean } = {}): ImagePreviewApi {
  if (scoped) {
    const state = ref<PreviewState | null>(null);
    const api = {
      state,
      openPreview: ({ objects, initialId }: { objects: PreviewState['objects'], initialId: PreviewState['initialId'] }) => {
        state.value = { objects: objects.map(object => ({ ...object })), initialId };
      },
      closePreview: () => {
        state.value = null;
      },
      ...((__BUILD_MODE_IS_TEST__ && {
        TEST_ONLY: {},
      }) || {}),
    };
    provide(PREVIEW_KEY, api);
    return api;
  }

  const injected = inject(PREVIEW_KEY, null);
  if (injected) return {
    ...injected,
    ...((__BUILD_MODE_IS_TEST__ && {
      TEST_ONLY: {},
    }) || {}),
  };

  // Fallback to local ref if not provided (allows simple local use in a component)
  const state = ref<PreviewState | null>(null);
  return {
    state,
    openPreview: ({ objects, initialId }: { objects: PreviewState['objects'], initialId: PreviewState['initialId'] }) => {
      state.value = { objects: objects.map(object => ({ ...object })), initialId };
    },
    closePreview: () => {
      state.value = null;
    },
    ...((__BUILD_MODE_IS_TEST__ && {
      TEST_ONLY: {},
    }) || {}),
  };
}

// Export internal state and logic used only for testing here. Do not reference these in production logic.
// ESLint-required for TypeScript modules.
export const TEST_ONLY = {
};
